FONTS: Dict[str, Dict[str, Dict[str, Any]]] = {
    "cursive_script": CURSIVE_SCRIPT,
    "script_complex": SCRIPT_COMPLEX,
    "simplex_sans": SIMPLEX_SANS,
    "duplex_sans": DUPLEX_SANS,
    "roman_serif": ROMAN_SERIF,
    "block_stencil": BLOCK_STENCIL,
}

def get_available_fonts() -> Dict[str, str]:
    return FONT_METADATA

def get_glyph(char: str, font_name: str = "cursive_script", curve_subdivisions: int = 4) -> Dict[str, Any]:
    font_dict = FONTS.get(font_name, CURSIVE_SCRIPT)
    raw = font_dict.get(char, SIMPLEX_SANS.get(char, SIMPLEX_SANS.get("?", {"w": 4.0, "strokes": []})))

    if curve_subdivisions > 1:
        smoothed_strokes = [smooth_stroke(stroke, steps=curve_subdivisions) for stroke in raw["strokes"]]
        return {"w": raw["w"], "strokes": smoothed_strokes}
    return raw
